{"tiddlers": {"$:/plugins/collaborative-blog/styles": {"title": "$:/plugins/collaborative-blog/styles", "tags": "$:/tags/Stylesheet", "type": "text/css", "text": "/* ===== HIDE WIKI ELEMENTS ===== */

/* Hide default edit, save, new buttons */
.tc-page-controls,
.tc-tiddler-controls,
.tc-sidebar-scrollable,
button[aria-label="new tiddler"],
button[aria-label="save wiki"],
.tc-topbar-right,
.tc-unfold-banner {
  display: none !important;
}

/* Hide the default sidebar */
.tc-sidebar-scrollable {
  display: none !important;
}

/* ===== LAYOUT STRUCTURE ===== */

/* Main page container - add left margin for sidebar */
.tc-page-container {
  margin-left: var(--cb-sidebar-width);
  max-width: var(--cb-content-max-width);
  padding: 2rem;
}

/* Story river (main content area) */
.tc-story-river {
  width: 100%;
  padding: 0;
}

/* ===== TYPOGRAPHY ===== */

/* Base font styling - professional, readable */
html body.tc-body {
  font-family: var(--cb-font-body);
  line-height: 1.7;
  color: var(--cb-text-primary);
  background: var(--cb-bg-page);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--cb-font-heading);
  color: var(--cb-heading);
  font-weight: 600;
  line-height: 1.3;
}

/* ===== LEFT SIDEBAR NAVIGATION ===== */

.cb-sidebar {
  position: fixed;
  left: 0;
  top: 0;
  width: var(--cb-sidebar-width);
  height: 100vh;
  background: var(--cb-bg-sidebar);
  color: var(--cb-text-inverse);
  padding: 2rem 1.5rem;
  overflow-y: auto;
  box-shadow: var(--cb-shadow-sidebar);
  z-index: 1000;
}

.cb-site-title {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--cb-text-white);
  font-family: var(--cb-font-heading);
}

.cb-site-subtitle {
  font-size: 0.9rem;
  color: var(--cb-text-light);
  margin-bottom: 2rem;
  font-style: italic;
}

.cb-nav-menu {
  list-style: none;
  padding: 0;
  margin: 0;
}

.cb-nav-menu li {
  margin-bottom: 0.5rem;
}

.cb-nav-menu a {
  color: var(--cb-text-inverse);
  text-decoration: none;
  display: block;
  padding: 0.5rem 0.75rem;
  border-radius: var(--cb-radius-sm);
  transition: background 0.2s;
  font-family: var(--cb-font-sans);
}

.cb-nav-menu a:hover {
  background: var(--cb-border-medium);
  color: var(--cb-text-white);
}

.cb-admin-link {
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid var(--cb-border-medium);
}

.cb-admin-link a,
.cb-admin-link button {
  color: var(--cb-text-light);
  font-size: 0.85rem;
  text-decoration: none;
  opacity: 0.6;
  transition: opacity 0.2s;
}

.cb-admin-link a:hover,
.cb-admin-link button:hover {
  opacity: 1;
  color: var(--cb-text-inverse);
}

/* Sidebar sections (Recently Updated, Favorite Articles) */
.cb-sidebar-section {
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--cb-border-medium);
}

.cb-sidebar-heading {
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--cb-text-light);
  margin-bottom: 0.75rem;
  font-family: var(--cb-font-sans);
}

.cb-sidebar-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.cb-sidebar-list-item {
  margin-bottom: 0.5rem;
  font-size: 0.9rem;
}

.cb-sidebar-list-item a {
  color: var(--cb-text-inverse);
  text-decoration: none;
  display: block;
  padding: 0.4rem 0.5rem;
  border-radius: var(--cb-radius-md);
  transition: background 0.2s;
  line-height: 1.4;
}

.cb-sidebar-list-item a:hover {
  background: var(--cb-border-medium);
  color: var(--cb-text-white);
}

.cb-sidebar-list-item.cb-sidebar-empty {
  color: var(--cb-text-meta);
  font-style: italic;
  font-size: 0.85rem;
  padding: 0.4rem 0.5rem;
}

/* ===== BLOG POST STYLING ===== */

.cb-post,
.cb-page {
  background: var(--cb-bg-content);
  padding: 2.5rem;
  margin-bottom: 2rem;
  border-radius: var(--cb-radius-sm);
  box-shadow: var(--cb-shadow-md);
}

.cb-post-title {
  font-size: 2.25rem;
  margin-bottom: 1rem;
  color: var(--cb-heading);
  line-height: 1.2;
}

.cb-post-meta {
  color: var(--cb-text-meta);
  font-size: 0.95rem;
  margin-bottom: 1.5rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--cb-border-light);
  font-family: var(--cb-font-sans);
}

.cb-post-author {
  font-weight: 600;
  color: var(--cb-heading-light);
}

.cb-post-date {
  margin-left: 1rem;
}

.cb-post-categories {
  margin-left: 1rem;
}

.cb-post-content {
  font-size: 1.1rem;
  line-height: 1.8;
}

.cb-post-content p {
  margin-bottom: 1.2rem;
}

/* ===== HOMEPAGE POST LIST ===== */

.cb-post-list-item {
  background: var(--cb-bg-content);
  padding: 2rem;
  margin-bottom: 1.5rem;
  border-radius: var(--cb-radius-sm);
  box-shadow: var(--cb-shadow-sm);
  transition: box-shadow 0.2s;
}

.cb-post-list-item:hover {
  box-shadow: var(--cb-shadow-lg);
}

.cb-post-list-title {
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.cb-post-list-title a {
  color: var(--cb-heading);
  text-decoration: none;
}

.cb-post-list-title a:hover {
  color: var(--cb-accent);
}

.cb-post-excerpt {
  color: var(--cb-text-secondary);
  line-height: 1.6;
  margin-top: 1rem;
}

.cb-read-more {
  display: inline-block;
  margin-top: 1rem;
  color: var(--cb-accent);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
  font-family: var(--cb-font-sans);
}

.cb-read-more:hover {
  color: var(--cb-accent-hover);
}

/* ===== FEATURED POST ===== */

.cb-featured-post {
  background: var(--cb-bg-featured);
  color: var(--cb-text-white);
  padding: 3rem;
  margin-bottom: 2rem;
  border-radius: var(--cb-radius-lg);
  box-shadow: var(--cb-shadow-xl);
}

.cb-featured-badge {
  display: inline-block;
  background: rgba(255,255,255,0.2);
  padding: 0.25rem 0.75rem;
  border-radius: var(--cb-radius-md);
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 1rem;
  font-weight: 600;
}

.cb-featured-post .cb-post-list-title a {
  color: var(--cb-text-white);
  font-size: 2.5rem;
}

.cb-featured-post .cb-post-meta,
.cb-featured-post .cb-post-excerpt {
  color: rgba(255,255,255,0.9);
}

.cb-featured-post .cb-read-more {
  color: var(--cb-text-white);
  border: 2px solid rgba(255,255,255,0.5);
  padding: 0.5rem 1.5rem;
  border-radius: var(--cb-radius-md);
  display: inline-block;
  margin-top: 1rem;
}

.cb-featured-post .cb-read-more:hover {
  background: rgba(255,255,255,0.1);
  border-color: var(--cb-text-white);
}

/* ===== CATEGORY TAGS ===== */

.cb-category-tag {
  display: inline-block;
  background: var(--cb-border-light);
  color: var(--cb-heading-light);
  padding: 0.25rem 0.75rem;
  border-radius: var(--cb-radius-md);
  font-size: 0.85rem;
  margin-right: 0.5rem;
  text-decoration: none;
  font-family: var(--cb-font-sans);
}

.cb-category-tag:hover {
  background: var(--cb-text-light);
  color: var(--cb-heading);
}

/* ===== TABLE OF CONTENTS ===== */

.cb-toc {
  background: var(--cb-bg-content);
  padding: 2rem;
  border-radius: var(--cb-radius-sm);
  box-shadow: var(--cb-shadow-md);
}

.cb-toc h2 {
  margin-top: 0;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--cb-accent);
}

.cb-toc-list {
  list-style: none;
  padding: 0;
}

.cb-toc-list li {
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--cb-border-light);
}

.cb-toc-list li:last-child {
  border-bottom: none;
}

/* ===== ADMIN PANEL ===== */

.cb-admin-panel {
  position: fixed;
  top: 0;
  left: var(--cb-sidebar-width);
  right: 0;
  background: var(--cb-bg-content);
  border-bottom: 3px solid #e74c3c;
  padding: 1.5rem;
  box-shadow: var(--cb-shadow-md);
  z-index: 999;
  display: none;
}

.cb-admin-panel.active {
  display: block;
}

.cb-admin-panel h3 {
  margin-top: 0;
  color: #e74c3c;
  font-size: 1.25rem;
}

.cb-admin-actions {
  display: flex;
  gap: 1rem;
  margin-top: 1rem;
  flex-wrap: wrap;
}

.cb-admin-button {
  background: var(--cb-accent);
  color: var(--cb-text-white);
  border: none;
  padding: 0.5rem 1.25rem;
  border-radius: var(--cb-radius-md);
  cursor: pointer;
  font-family: var(--cb-font-sans);
  font-size: 0.95rem;
  transition: background 0.2s;
}

.cb-admin-button:hover {
  background: var(--cb-accent-hover);
}

.cb-admin-button.danger {
  background: #e74c3c;
}

.cb-admin-button.danger:hover {
  background: #c0392b;
}

/* Post Type Selector in Admin Panel */
.cb-post-type-group {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  padding: 0.75rem;
  background: var(--cb-border-light);
  border-radius: var(--cb-radius-md);
}

.cb-post-type-label {
  font-weight: 600;
  color: var(--cb-heading);
  font-size: 0.95rem;
  margin-right: 0.5rem;
}

.cb-post-type-button {
  padding: 0.4rem 1rem !important;
  font-size: 0.9rem !important;
}

.cb-event-button {
  background: #f39c12 !important;
}

.cb-event-button:hover {
  background: #e67e22 !important;
}

.cb-gallery-button {
  background: #9b59b6 !important;
}

.cb-gallery-button:hover {
  background: #8e44ad !important;
}

.cb-video-button {
  background: #e74c3c !important;
}

.cb-video-button:hover {
  background: #c0392b !important;
}

.cb-quote-button {
  background: #16a085 !important;
}

.cb-quote-button:hover {
  background: #138871 !important;
}

/* ===== RESPONSIVE DESIGN ===== */

@media (max-width: 768px) {
  .cb-sidebar {
    width: 100%;
    height: auto;
    position: relative;
  }

  .tc-page-container {
    margin-left: 0;
    padding: 1rem;
  }

  .cb-admin-panel {
    left: 0;
  }
}
"}, "$:/plugins/collaborative-blog/Navigation": {"title": "$:/plugins/collaborative-blog/Navigation", "tags": "$:/tags/PageTemplate", "type": "text/vnd.tiddlywiki", "text": "<!--
  Left Sidebar Navigation Component

  This template creates the fixed left sidebar navigation that appears on every page
  Tagged with $:/tags/PageTemplate to render as part of the page template

  Features:
  - Fixed position sidebar (280px wide on desktop)
  - Site title and subtitle displayed at top
  - Main navigation menu
  - Discrete "Admin" link to toggle admin panel
  - Responsive design (full width on mobile)

  Customization:
  - Edit $:/SiteTitle and $:/SiteSubtitle to change site branding
  - Modify the menu items below to add/remove navigation links
  - Styles defined in styles.tid (.cb-sidebar, .cb-nav-menu, etc.)
-->

<!-- Macro: site-title
     Retrieves the site title from $:/SiteTitle tiddler
     Allows users to change the site title in one place
-->
\define site-title()
<$view tiddler="$:/SiteTitle" field="text"/>
\end

<!-- Macro: site-subtitle
     Retrieves the site subtitle/tagline from $:/SiteSubtitle tiddler
     Displayed below the main title in muted text
-->
\define site-subtitle()
<$view tiddler="$:/SiteSubtitle" field="text"/>
\end

<div class="cb-sidebar">
  <!-- Site branding: title and subtitle -->
  <div class="cb-site-title"><<site-title>></div>
  <div class="cb-site-subtitle"><<site-subtitle>></div>

  <!-- Main navigation menu
       To customize: Add or remove <li> items below
       Each <$link> creates a link to the specified tiddler title
  -->
  <nav>
    <ul class="cb-nav-menu">
      <li><$link to="Home">Home</$link></li>
      <li><$link to="About">About</$link></li>
      <li><$link to="All Posts">Archive</$link></li>
      <li><$link to="Categories">Categories</$link></li>
      <li><$link to="Contact">Contact</$link></li>
    </ul>
  </nav>

  <!-- Recently Updated Section
       Shows the 5 most recently modified posts
       Uses TiddlyWiki's automatic 'modified' field for sorting
  -->
  <div class="cb-sidebar-section">
    <h4 class="cb-sidebar-heading">Recently Updated</h4>
    <ul class="cb-sidebar-list">
      <$list filter="[tag[Post]!tag[Draft]has[modified]!sort[modified]limit[5]]">
        <li class="cb-sidebar-list-item">
          <$link to=<<currentTiddler>>>
            <$view field="title"/>
          </$link>
        </li>
      </$list>
    </ul>
  </div>

  <!-- Favorite Articles Section
       Shows posts tagged with "Favorite"
       Limited to 5 items
  -->
  <div class="cb-sidebar-section">
    <h4 class="cb-sidebar-heading">Favorite Articles</h4>
    <ul class="cb-sidebar-list">
      <$list filter="[tag[Post]tag[Favorite]!tag[Draft]limit[5]]">
        <li class="cb-sidebar-list-item">
          <$link to=<<currentTiddler>>>
            <$view field="title"/>
          </$link>
        </li>
      </$list>
      <$list filter="[tag[Post]tag[Favorite]!tag[Draft]count[]compare:number:eq[0]]" variable="null">
        <li class="cb-sidebar-list-item cb-sidebar-empty">
          No favorites yet
        </li>
      </$list>
    </ul>
  </div>

  <!-- Admin Panel Toggle
       Toggles the visibility of the admin panel
       Authentication is handled by Cloudflare saver when you save changes
  -->
  <div class="cb-admin-link">
    <$button class="tc-btn-invisible tc-tiddlylink">
      Admin
      <$action-setfield $tiddler="$:/state/admin-panel-visible" text={{$:/state/admin-panel-visible}} />
      <$list filter="[[$:/state/admin-panel-visible]get[text]match[yes]]">
        <$action-setfield $tiddler="$:/state/admin-panel-visible" text="no" />
      </$list>
      <$list filter="[[$:/state/admin-panel-visible]get[text]!match[yes]]">
        <$action-setfield $tiddler="$:/state/admin-panel-visible" text="yes" />
      </$list>
    </$button>
  </div>
</div>
"}, "$:/plugins/collaborative-blog/AdminPanel": {"title": "$:/plugins/collaborative-blog/AdminPanel", "tags": "$:/tags/PageTemplate", "type": "text/vnd.tiddlywiki", "text": "<!--
  Admin Panel Component

  This panel appears at the top of the page when activated via the "Admin" link in the sidebar
  Provides quick access to common blog management tasks

  Features:
  - Hidden by default (only renders when state tiddler is "yes")
  - Activated by clicking "Admin" link which toggles state tiddler
  - Contains buttons for creating posts, pages, and accessing settings
  - Fixed position at top of page when active

  State management: Uses $:/state/admin-panel-visible tiddler to track visibility
  Authentication: Handled by Cloudflare saver when saving changes
-->

<!-- Only render admin panel if panel visibility is "yes" -->
<$list filter="[[$:/state/admin-panel-visible]get[text]match[yes]]" variable="null">
<div class="cb-admin-panel active">
  <h3>Admin Panel</h3>
  <div class="cb-admin-actions">

    <!-- New Post Type Selector -->
    <div class="cb-post-type-group">
      <div class="cb-post-type-label">Create New:</div>

      <!-- Standard Post -->
      <$button class="cb-admin-button cb-post-type-button" aria-label="Create standard blog post">
        📝 Post
        <$action-sendmessage $message="tm-new-tiddler" tags="Post" />
      </$button>

      <!-- Event Post -->
      <$button class="cb-admin-button cb-post-type-button cb-event-button" aria-label="Create event post">
        📅 Event
        <$action-sendmessage $message="tm-new-tiddler" tags="Post Event" event-status="upcoming" />
      </$button>

      <!-- Gallery Post -->
      <$button class="cb-admin-button cb-post-type-button cb-gallery-button" aria-label="Create gallery post">
        🖼️ Gallery
        <$action-sendmessage $message="tm-new-tiddler" tags="Post Gallery" />
      </$button>

      <!-- Video Post -->
      <$button class="cb-admin-button cb-post-type-button cb-video-button" aria-label="Create video post">
        🎥 Video
        <$action-sendmessage $message="tm-new-tiddler" tags="Post Video" />
      </$button>

      <!-- Quote Post -->
      <$button class="cb-admin-button cb-post-type-button cb-quote-button" aria-label="Create quote post">
        💬 Quote
        <$action-sendmessage $message="tm-new-tiddler" tags="Post Quote" />
      </$button>
    </div>

    <!-- New Page Button
         Creates a new tiddler with the "Page" tag pre-applied
         ARIA: Screen readers will announce "Create new static page"
    -->
    <$button class="cb-admin-button" aria-label="Create new static page">
      {{$:/core/images/new-button}} New Page
      <$action-sendmessage $message="tm-new-tiddler" tags="Page" />
    </$button>

    <!-- Control Panel Button
         Opens TiddlyWiki's control panel modal for advanced settings
         ARIA: Screen readers will announce "Open TiddlyWiki control panel"
    -->
    <$button class="cb-admin-button" aria-label="Open TiddlyWiki control panel">
      {{$:/core/images/options-button}} Control Panel
      <$action-sendmessage $message="tm-modal" $param="$:/ControlPanel" />
    </$button>

    <!-- Save Changes Button
         Triggers the save operation to download the updated HTML file
         ARIA: Screen readers will announce "Save all changes to wiki"
    -->
    <$button class="cb-admin-button" aria-label="Save all changes to wiki">
      {{$:/core/images/save-button}} Save Changes
      <$action-sendmessage $message="tm-save-wiki" />
    </$button>

    <!-- Advanced Search Button
         Opens TiddlyWiki's advanced search modal
         ARIA: Screen readers will announce "Open advanced search"
    -->
    <$button class="cb-admin-button" aria-label="Open advanced search">
      {{$:/core/images/advanced-search-button}} Advanced Search
      <$action-sendmessage $message="tm-modal" $param="$:/AdvancedSearch" />
    </$button>
  </div>
</div>
</$list>
"}, "$:/plugins/collaborative-blog/ViewTemplate/SystemTiddler": {"title": "$:/plugins/collaborative-blog/ViewTemplate/SystemTiddler", "tags": "$:/tags/ViewTemplate", "type": "text/vnd.tiddlywiki", "list-before": "$:/core/ui/ViewTemplate/body", "text": "<!--
  ViewTemplate to hide system tiddlers from story view

  System tiddlers (those starting with $:/) should not appear in the blog's story river
  They should only be accessible via modals (Control Panel, Advanced Search, etc.)

  This template runs before the body template and prevents system tiddlers from rendering
  Exception: Our own plugin tiddlers that need to be visible are excluded
-->

<$list filter="[<currentTiddler>prefix[$:/]!prefix[$:/plugins/collaborative-blog]]" variable="null">
  <div style="display: none;">
    <!-- System tiddler hidden from story view -->
  </div>
</$list>
"}, "$:/plugins/collaborative-blog/ViewTemplate/Post": {"title": "$:/plugins/collaborative-blog/ViewTemplate/Post", "tags": "$:/tags/ViewTemplate", "type": "text/vnd.tiddlywiki", "list-after": "$:/core/ui/ViewTemplate/title", "text": "<!--
  ViewTemplate for Blog Posts

  This template activates when viewing any tiddler tagged with "Post"
  It replaces the default TiddlyWiki view with a blog-style post layout

  Key features:
  - Shows post title, author, date, and category tags
  - Displays full post content
  - Provides back navigation to homepage
  - Automatically hides wiki controls via CSS

  list-after: Ensures this template runs after the core title template
-->

<!-- Macro: post-body
     Renders the complete blog post layout including title, metadata, content, and navigation
     Context: Called only when currentTiddler has "Post" tag
-->
\define post-body()
<div class="cb-post">
  <!-- Post title -->
  <h1 class="cb-post-title"><$view field="title"/></h1>

  <!-- Post metadata section: author, date, categories -->
  <div class="cb-post-meta">
    <!-- Display author name if the author field exists -->
    <$list filter="[<currentTiddler>has[author]]" variable="null">
      <span class="cb-post-author">
        By <$view field="author"/>
      </span>
    </$list>

    <!-- Display formatted date if the date field exists (YYYYMMDD -> DD MMM YYYY) -->
    <$list filter="[<currentTiddler>has[date]]" variable="null">
      <span class="cb-post-date">
        <$view field="date" format="date" template="DD MMM YYYY"/>
      </span>
    </$list>

    <!-- Display category tags (filters out system tags: Post, Featured, Draft) -->
    <$list filter="[<currentTiddler>tags[]!tag[Post]!tag[Featured]!tag[Draft]]" variable="tag">
      <span class="cb-post-categories">
        <a class="cb-category-tag" href={{{ [<tag>addprefix[#]] }}}>
          <<tag>>
        </a>
      </span>
    </$list>
  </div>

  <!-- Full post content (transcluded from the text field) -->
  <div class="cb-post-content">
    <$transclude field="text" mode="block"/>
  </div>

  <!-- Navigation: Back to homepage link -->
  <div style="margin-top: 3rem; padding-top: 2rem; border-top: 1px solid #ecf0f1;">
    <$link to="Home" style="color: #3498db; text-decoration: none;">← Back to Home</$link>
  </div>
</div>
\end

<!-- Template activation: Only render this template for tiddlers tagged with "Post"
     Filter: [<currentTiddler>tag[Post]]
     This prevents the blog post layout from appearing on pages, admin tiddlers, etc.
-->
<$list filter="[<currentTiddler>tag[Post]]" variable="null">
  <<post-body>>
</$list>
"}, "$:/plugins/collaborative-blog/ViewTemplate/Page": {"title": "$:/plugins/collaborative-blog/ViewTemplate/Page", "tags": "$:/tags/ViewTemplate", "type": "text/vnd.tiddlywiki", "list-after": "$:/plugins/collaborative-blog/ViewTemplate/Post", "text": "<!--
  ViewTemplate for Static Pages

  This template activates when viewing any tiddler tagged with "Page"
  It provides a simpler layout than blog posts (no author, date, or category metadata)

  Use this for static content like:
  - About page
  - Contact page
  - Privacy policy
  - Terms of service
  - Project pages

  list-after: Runs after the Post ViewTemplate to avoid conflicts
-->

<!-- Macro: page-body
     Renders a simple page layout with title, content, and navigation
     Simpler than post-body - no metadata fields
     Context: Called only when currentTiddler has "Page" tag
-->
\define page-body()
<div class="cb-page">
  <!-- Page title -->
  <h1 class="cb-post-title"><$view field="title"/></h1>

  <!-- Page content (transcluded from the text field) -->
  <div class="cb-post-content">
    <$transclude field="text" mode="block"/>
  </div>

  <!-- Navigation: Back to homepage link -->
  <div style="margin-top: 3rem; padding-top: 2rem; border-top: 1px solid #ecf0f1;">
    <$link to="Home" style="color: #3498db; text-decoration: none;">← Back to Home</$link>
  </div>
</div>
\end

<!-- Template activation: Only render this template for tiddlers tagged with "Page"
     Filter: [<currentTiddler>tag[Page]]
     This prevents the page layout from appearing on posts, admin tiddlers, etc.
-->
<$list filter="[<currentTiddler>tag[Page]]" variable="null">
  <<page-body>>
</$list>
"}, "$:/plugins/collaborative-blog/readme": {"title": "$:/plugins/collaborative-blog/readme", "type": "text/vnd.tiddlywiki", "text": "! Collaborative Blog Plugin

This plugin transforms TiddlyWiki into a WordPress-style collaborative blog with a clean, professional interface.

!! Features

''Content & Publishing:''
* Clean blog layout with hidden wiki controls
* Multiple author support with attribution
* Featured posts and favorite articles
* Custom post types: Events, Galleries, Videos, Quotes
* Categories and tags for organization
* Post archive and table of contents
* Draft management
* Static pages support

''User Interface:''
* Left sidebar navigation with recently updated posts
* 5 professional themes (Historical, Modern, Dark, Vibrant, Professional)
* Enhanced search with filters (post type, category, author)
* Responsive design for mobile and desktop
* Discrete admin panel with post type selector

''Automatic Saving & Deployment:''
* Automatic GitHub saving via Cloudflare Functions (integrated)
* Password-protected saves with session management
* Save notifications and statistics
* Real-time deployment via Cloudflare Pages

''Analytics & Insights:''
* Privacy-friendly analytics (Plausible, Simple Analytics)
* Google Analytics (GA4) support
* Custom analytics provider support
* Easy Control Panel configuration

!! Quick Start

!!! Creating Posts

# Click ''Admin'' in the left sidebar
# Choose post type:
#* 📝 ''Post'' - Standard blog post
#* 📅 ''Event'' - Event with date, time, location, RSVP
#* 🖼️ ''Gallery'' - Image gallery with grid layout
#* 🎥 ''Video'' - YouTube/Vimeo embed with transcript
#* 💬 ''Quote'' - Featured quotation with attribution
# Add fields:
#* Title: Your post title
#* Tags: Auto-added based on post type, plus category tags
#* Author: Your name
#* Date: YYYYMMDD format (e.g., `20251118`)
#* Excerpt: Brief summary (recommended)
# Add post-type specific fields (event-date, video-url, quote-text, etc.)
# Write your content
# Save

!!! Using Search

# Click ''Search'' tab in left sidebar
# Type query to see instant results
# Click category tags to filter
# Click "View All Results" for advanced search with filters

!!! Changing Themes

# Navigate to Control Panel → Appearance
# Select from 5 professional themes
# Theme applies immediately

!!! Setting Up Analytics

# Go to Control Panel → Settings → Analytics
# Enable analytics and choose provider
# Configure provider-specific settings
# Save to activate

!!! Creating Featured Posts

Add `Featured` to tags (e.g., `Post Featured News`)

!!! Creating Static Pages

# Click ''New Page'' in admin panel
# Add Title and set Tags to `Page`
# Write content and save

!!! Saving as Draft

Add `Draft` to tags to hide from public view

!! Customization

''Site Identity:''
* Edit `$:/SiteTitle` and `$:/SiteSubtitle` to change site name

''Themes:''
* Choose from 5 built-in themes in Control Panel → Appearance
* Edit `$:/plugins/collaborative-blog/theme-controller` to create custom themes
* Modify 40+ CSS variables for complete design control

''Navigation:''
* Edit `$:/plugins/collaborative-blog/Navigation` to customize menu links

''Advanced Styling:''
* Edit `$:/plugins/collaborative-blog/styles` for base styles and components
* All styles use CSS variables for easy theming

!! Version

Current version: ''2.2.0''

''What's New in v2.2.0:''
* Enhanced search with filters
* Analytics integration (Plausible, Simple Analytics, Google Analytics, Custom)

''What's New in v2.1.0:''
* 5 professional themes with one-click switching
* Custom post types (Event, Gallery, Video, Quote)

!! Documentation

For complete documentation, troubleshooting, and setup guides, see:
* [[GitHub Repository|https://github.com/BenSweaterVest/TiddlySite]]
* [[README.md|https://github.com/BenSweaterVest/TiddlySite/blob/main/README.md]]
* [[Release Notes|https://github.com/BenSweaterVest/TiddlySite/blob/main/RELEASE_NOTES_v2.2.0.md]]

!! Automatic Saving & Deployment

This plugin includes integrated automatic saving to GitHub via Cloudflare Functions.

''What's included:''

* Beautiful blog UI and editing experience
* Automatic GitHub save mechanism (built-in)
* Real-time deployment via Cloudflare Pages
* Password-protected saves
* Save statistics and connection monitoring

''Setup:'' Configure the Cloudflare saver in the Control Panel → Saving tab. You'll need to set up a Cloudflare Pages site with a GitHub repository containing a `functions/save.js` file.

!! Support

* GitHub: https://github.com/BenSweaterVest/TiddlySite
* TiddlyWiki Community: https://talk.tiddlywiki.org/
"}, "$:/plugins/collaborative-blog/ViewTemplate/Post/Event": {"title": "$:/plugins/collaborative-blog/ViewTemplate/Post/Event", "tags": "$:/tags/ViewTemplate", "type": "text/vnd.tiddlywiki", "text": "\define isEventPost() [all[current]tag[Post]tag[Event]]

<$list filter=<<isEventPost>> variable="null">

<div class="cb-post cb-event-post">

<!-- Event Badge -->
<div class="cb-event-badge">
📅 EVENT
</div>

<!-- Post Title -->
<h1 class="cb-post-title">
<$view field="title"/>
</h1>

<!-- Event Meta Information -->
<div class="cb-post-meta cb-event-meta">

<!-- Author -->
<$list filter="[all[current]has[author]]" variable="null">
<span class="cb-post-author">By <$view field="author"/></span>
</$list>

<!-- Date -->
<$list filter="[all[current]has[date]]" variable="null">
<span class="cb-post-date">
Posted: <$view field="date" format="date" template="DD MMM YYYY"/>
</span>
</$list>

</div>

<!-- Event Details Box -->
<div class="cb-event-details">

<h3 style="margin-top: 0; color: var(--cb-accent);">Event Details</h3>

<!-- Event Date -->
<$list filter="[all[current]has[event-date]]" variable="null">
<div class="cb-event-detail-item">
<strong>📆 Date:</strong>
<$view field="event-date" format="date" template="DDD, DD MMM YYYY"/>
</div>
</$list>

<!-- Event Time -->
<$list filter="[all[current]has[event-time]]" variable="null">
<div class="cb-event-detail-item">
<strong>🕐 Time:</strong>
<$view field="event-time"/>
</div>
</$list>

<!-- Event Location -->
<$list filter="[all[current]has[event-location]]" variable="null">
<div class="cb-event-detail-item">
<strong>📍 Location:</strong>
<$view field="event-location"/>
</div>
</$list>

<!-- Event Status -->
<$list filter="[all[current]has[event-status]]" variable="null">
<div class="cb-event-detail-item">
<strong>Status:</strong>
<span class="cb-event-status cb-event-status-{{{ [all[current]get[event-status]] }}}">
<$view field="event-status"/>
</span>
</div>
</$list>

<!-- RSVP Link -->
<$list filter="[all[current]has[event-rsvp-link]]" variable="null">
<div class="cb-event-detail-item" style="margin-top: 15px;">
<a href={{{ [all[current]get[event-rsvp-link]] }}} class="cb-event-rsvp-button" target="_blank" rel="noopener">
RSVP / Register
</a>
</div>
</$list>

</div>

<!-- Post Content -->
<div class="cb-post-content">
<$transclude mode="block"/>
</div>

<!-- Categories/Tags -->
<$list filter="[all[current]tags[]!prefix[$:/]!match[Post]!match[Event]!match[Draft]!match[Featured]!match[Favorite]]" variable="tag">
<a href={{{ [<tag>encodeuricomponent[]addprefix[#]] }}} class="cb-category-tag">
<$text text=<<tag>>/>
</a>
</$list>

</div>

</$list>

<style>
.cb-event-post {
  position: relative;
}

.cb-event-badge {
  display: inline-block;
  background: var(--cb-accent);
  color: var(--cb-text-white);
  padding: 0.4rem 1rem;
  border-radius: var(--cb-radius-md);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  margin-bottom: 1.5rem;
}

.cb-event-details {
  background: linear-gradient(135deg, var(--cb-accent-light) 0%, var(--cb-accent) 100%);
  color: var(--cb-text-white);
  padding: 2rem;
  border-radius: var(--cb-radius-lg);
  margin: 2rem 0;
  box-shadow: var(--cb-shadow-lg);
}

.cb-event-detail-item {
  margin: 0.75rem 0;
  font-size: 1.05rem;
}

.cb-event-detail-item strong {
  display: inline-block;
  min-width: 100px;
}

.cb-event-status {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  border-radius: var(--cb-radius-sm);
  font-size: 0.9em;
  font-weight: 600;
  text-transform: uppercase;
}

.cb-event-status-upcoming {
  background: rgba(255,255,255,0.3);
  color: var(--cb-text-white);
}

.cb-event-status-past {
  background: rgba(0,0,0,0.2);
  color: rgba(255,255,255,0.7);
}

.cb-event-status-cancelled {
  background: #e74c3c;
  color: var(--cb-text-white);
}

.cb-event-rsvp-button {
  display: inline-block;
  background: var(--cb-text-white);
  color: var(--cb-accent);
  padding: 0.75rem 2rem;
  border-radius: var(--cb-radius-md);
  text-decoration: none;
  font-weight: 700;
  font-size: 1.05rem;
  transition: transform 0.2s, box-shadow 0.2s;
  box-shadow: 0 4px 6px rgba(0,0,0,0.2);
}

.cb-event-rsvp-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 12px rgba(0,0,0,0.3);
}
</style>
"}, "$:/plugins/collaborative-blog/ViewTemplate/Post/Gallery": {"title": "$:/plugins/collaborative-blog/ViewTemplate/Post/Gallery", "tags": "$:/tags/ViewTemplate", "type": "text/vnd.tiddlywiki", "text": "\define isGalleryPost() [all[current]tag[Post]tag[Gallery]]

<$list filter=<<isGalleryPost>> variable="null">

<div class="cb-post cb-gallery-post">

<!-- Gallery Badge -->
<div class="cb-gallery-badge">
🖼️ GALLERY
</div>

<!-- Post Title -->
<h1 class="cb-post-title">
<$view field="title"/>
</h1>

<!-- Post Meta -->
<div class="cb-post-meta">

<!-- Author -->
<$list filter="[all[current]has[author]]" variable="null">
<span class="cb-post-author">By <$view field="author"/></span>
</$list>

<!-- Date -->
<$list filter="[all[current]has[date]]" variable="null">
<span class="cb-post-date">
<$view field="date" format="date" template="DD MMM YYYY"/>
</span>
</$list>

</div>

<!-- Post Content / Description -->
<div class="cb-post-content">
<$transclude mode="block"/>
</div>

<!-- Gallery Images -->
<$list filter="[all[current]has[gallery-images]]" variable="null">
<div class="cb-gallery-grid">

<$list filter="[all[current]get[gallery-images]split[,]]" variable="imagePath">
<div class="cb-gallery-item">
<img src={{{ [<imagePath>trim[]] }}} alt="Gallery image" class="cb-gallery-image"/>
</div>
</$list>

</div>
</$list>

<!-- Alternative: Gallery using tiddler tags -->
<$list filter="[all[current]!has[gallery-images]]" variable="null">
<div class="cb-gallery-grid">

<$list filter="[all[current]tagging[]type[image/jpeg]] [all[current]tagging[]type[image/png]] [all[current]tagging[]type[image/gif]]" variable="imageTitle">
<div class="cb-gallery-item">
<$image source=<<imageTitle>> class="cb-gallery-image"/>
<$list filter="[<imageTitle>has[caption]]">
<div class="cb-gallery-caption">
<$view tiddler=<<imageTitle>> field="caption"/>
</div>
</$list>
</div>
</$list>

</div>
</$list>

<!-- Categories/Tags -->
<div style="margin-top: 2rem;">
<$list filter="[all[current]tags[]!prefix[$:/]!match[Post]!match[Gallery]!match[Draft]!match[Featured]!match[Favorite]]" variable="tag">
<a href={{{ [<tag>encodeuricomponent[]addprefix[#]] }}} class="cb-category-tag">
<$text text=<<tag>>/>
</a>
</$list>
</div>

</div>

</$list>

<style>
.cb-gallery-post {
  position: relative;
}

.cb-gallery-badge {
  display: inline-block;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: var(--cb-text-white);
  padding: 0.4rem 1rem;
  border-radius: var(--cb-radius-md);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  margin-bottom: 1.5rem;
}

.cb-gallery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 1.5rem;
  margin: 2rem 0;
}

.cb-gallery-item {
  position: relative;
  overflow: hidden;
  border-radius: var(--cb-radius-lg);
  box-shadow: var(--cb-shadow-md);
  transition: transform 0.3s, box-shadow 0.3s;
  background: var(--cb-bg-content);
}

.cb-gallery-item:hover {
  transform: translateY(-4px);
  box-shadow: var(--cb-shadow-xl);
  cursor: pointer;
}

.cb-gallery-image {
  width: 100%;
  height: 250px;
  object-fit: cover;
  display: block;
  transition: transform 0.3s;
}

.cb-gallery-item:hover .cb-gallery-image {
  transform: scale(1.05);
}

.cb-gallery-caption {
  padding: 0.75rem 1rem;
  background: var(--cb-bg-content);
  font-size: 0.9rem;
  color: var(--cb-text-secondary);
  text-align: center;
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .cb-gallery-grid {
    grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
    gap: 1rem;
  }

  .cb-gallery-image {
    height: 180px;
  }
}
</style>
"}, "$:/plugins/collaborative-blog/ViewTemplate/Post/Video": {"title": "$:/plugins/collaborative-blog/ViewTemplate/Post/Video", "tags": "$:/tags/ViewTemplate", "type": "text/vnd.tiddlywiki", "text": "\define isVideoPost() [all[current]tag[Post]tag[Video]]

<$list filter=<<isVideoPost>> variable="null">

<div class="cb-post cb-video-post">

<!-- Video Badge -->
<div class="cb-video-badge">
🎥 VIDEO
</div>

<!-- Post Title -->
<h1 class="cb-post-title">
<$view field="title"/>
</h1>

<!-- Post Meta -->
<div class="cb-post-meta">

<!-- Author -->
<$list filter="[all[current]has[author]]" variable="null">
<span class="cb-post-author">By <$view field="author"/></span>
</$list>

<!-- Date -->
<$list filter="[all[current]has[date]]" variable="null">
<span class="cb-post-date">
<$view field="date" format="date" template="DD MMM YYYY"/>
</span>
</$list>

<!-- Video Duration -->
<$list filter="[all[current]has[video-duration]]" variable="null">
<span class="cb-video-duration">
⏱️ <$view field="video-duration"/>
</span>
</$list>

</div>

<!-- Video Embed -->
<$list filter="[all[current]has[video-url]]" variable="null">
<div class="cb-video-container">
<$let videoUrl={{{ [all[current]get[video-url]] }}}>

<!-- YouTube embed -->
<$list filter="[<videoUrl>search:title[youtube.com]] [<videoUrl>search:title[youtu.be]]" variable="null">
<$let videoId={{{ [<videoUrl>split[v=]last[]] [<videoUrl>split[/]last[]] +[first[]] }}}>
<iframe
  class="cb-video-iframe"
  src={{{ [<videoId>addprefix[https://www.youtube.com/embed/]] }}}
  frameborder="0"
  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
  allowfullscreen>
</iframe>
</$let>
</$list>

<!-- Vimeo embed -->
<$list filter="[<videoUrl>search:title[vimeo.com]]" variable="null">
<$let videoId={{{ [<videoUrl>split[/]last[]] }}}>
<iframe
  class="cb-video-iframe"
  src={{{ [<videoId>addprefix[https://player.vimeo.com/video/]] }}}
  frameborder="0"
  allow="autoplay; fullscreen; picture-in-picture"
  allowfullscreen>
</iframe>
</$let>
</$list>

<!-- Generic video link -->
<$list filter="[<videoUrl>!search:title[youtube.com]!search:title[youtu.be]!search:title[vimeo.com]]" variable="null">
<div class="cb-video-link-fallback">
<a href=<<videoUrl>> target="_blank" rel="noopener" class="cb-video-link-button">
▶️ Watch Video
</a>
</div>
</$list>

</$let>
</div>
</$list>

<!-- Post Content -->
<div class="cb-post-content">
<$transclude mode="block"/>
</div>

<!-- Video Transcript Toggle -->
<$list filter="[all[current]has[video-transcript]]" variable="null">
<details class="cb-video-transcript">
<summary style="cursor: pointer; font-weight: 600; padding: 1rem; background: var(--cb-border-light); border-radius: var(--cb-radius-md);">
📄 View Transcript
</summary>
<div style="padding: 1.5rem; margin-top: 1rem; background: var(--cb-bg-content); border-radius: var(--cb-radius-md); border-left: 4px solid var(--cb-accent);">
<$view field="video-transcript"/>
</div>
</details>
</$list>

<!-- Categories/Tags -->
<div style="margin-top: 2rem;">
<$list filter="[all[current]tags[]!prefix[$:/]!match[Post]!match[Video]!match[Draft]!match[Featured]!match[Favorite]]" variable="tag">
<a href={{{ [<tag>encodeuricomponent[]addprefix[#]] }}} class="cb-category-tag">
<$text text=<<tag>>/>
</a>
</$list>
</div>

</div>

</$list>

<style>
.cb-video-post {
  position: relative;
}

.cb-video-badge {
  display: inline-block;
  background: #e74c3c;
  color: var(--cb-text-white);
  padding: 0.4rem 1rem;
  border-radius: var(--cb-radius-md);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  margin-bottom: 1.5rem;
}

.cb-video-duration {
  margin-left: 1rem;
  color: var(--cb-text-meta);
  font-weight: 600;
}

.cb-video-container {
  position: relative;
  padding-bottom: 56.25%; /* 16:9 aspect ratio */
  height: 0;
  overflow: hidden;
  margin: 2rem 0;
  border-radius: var(--cb-radius-lg);
  box-shadow: var(--cb-shadow-xl);
}

.cb-video-iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border-radius: var(--cb-radius-lg);
}

.cb-video-link-fallback {
  padding: 3rem;
  background: linear-gradient(135deg, var(--cb-accent) 0%, var(--cb-accent-hover) 100%);
  border-radius: var(--cb-radius-lg);
  text-align: center;
}

.cb-video-link-button {
  display: inline-block;
  background: var(--cb-text-white);
  color: var(--cb-accent);
  padding: 1rem 3rem;
  border-radius: var(--cb-radius-lg);
  text-decoration: none;
  font-weight: 700;
  font-size: 1.2rem;
  box-shadow: var(--cb-shadow-lg);
  transition: transform 0.2s;
}

.cb-video-link-button:hover {
  transform: scale(1.05);
}

.cb-video-transcript {
  margin-top: 2rem;
}
</style>
"}, "$:/plugins/collaborative-blog/ViewTemplate/Post/Quote": {"title": "$:/plugins/collaborative-blog/ViewTemplate/Post/Quote", "tags": "$:/tags/ViewTemplate", "type": "text/vnd.tiddlywiki", "text": "\define isQuotePost() [all[current]tag[Post]tag[Quote]]

<$list filter=<<isQuotePost>> variable="null">

<div class="cb-post cb-quote-post">

<!-- Quote Badge -->
<div class="cb-quote-badge">
💬 QUOTE
</div>

<!-- Post Title (if provided) -->
<$list filter="[all[current]has[title]]" variable="null">
<h1 class="cb-post-title">
<$view field="title"/>
</h1>
</$list>

<!-- Post Meta -->
<div class="cb-post-meta">

<!-- Author (curator/poster) -->
<$list filter="[all[current]has[author]]" variable="null">
<span class="cb-post-author">Posted by <$view field="author"/></span>
</$list>

<!-- Date -->
<$list filter="[all[current]has[date]]" variable="null">
<span class="cb-post-date">
<$view field="date" format="date" template="DD MMM YYYY"/>
</span>
</$list>

</div>

<!-- Main Quote Block -->
<div class="cb-quote-container">

<div class="cb-quote-marks-open">"</div>

<div class="cb-quote-text">
<!-- Quote text field OR post content -->
<$list filter="[all[current]has[quote-text]]" variable="null">
<$view field="quote-text"/>
</$list>
<$list filter="[all[current]!has[quote-text]]" variable="null">
<$transclude mode="block"/>
</$list>
</div>

<div class="cb-quote-marks-close">"</div>

<!-- Quote Attribution -->
<div class="cb-quote-attribution">

<!-- Quote Author -->
<$list filter="[all[current]has[quote-author]]" variable="null">
<div class="cb-quote-author-name">
— <$view field="quote-author"/>
</div>
</$list>

<!-- Quote Source -->
<$list filter="[all[current]has[quote-source]]" variable="null">
<div class="cb-quote-source">
<$view field="quote-source"/>
</div>
</$list>

</div>

</div>

<!-- Additional Commentary (if post content exists and quote-text is used) -->
<$list filter="[all[current]has[quote-text]]" variable="null">
<$let postContent={{{ [all[current]get[text]] }}}>
<$list filter="[<postContent>!match[]]" variable="null">
<div class="cb-quote-commentary">
<h3>Commentary</h3>
<$transclude mode="block"/>
</div>
</$list>
</$let>
</$list>

<!-- Categories/Tags -->
<div style="margin-top: 2rem;">
<$list filter="[all[current]tags[]!prefix[$:/]!match[Post]!match[Quote]!match[Draft]!match[Featured]!match[Favorite]]" variable="tag">
<a href={{{ [<tag>encodeuricomponent[]addprefix[#]] }}} class="cb-category-tag">
<$text text=<<tag>>/>
</a>
</$list>
</div>

</div>

</$list>

<style>
.cb-quote-post {
  position: relative;
}

.cb-quote-badge {
  display: inline-block;
  background: #16a085;
  color: var(--cb-text-white);
  padding: 0.4rem 1rem;
  border-radius: var(--cb-radius-md);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.5px;
  margin-bottom: 1.5rem;
}

.cb-quote-container {
  position: relative;
  background: linear-gradient(135deg, var(--cb-accent-light) 0%, var(--cb-accent) 100%);
  padding: 3rem 2.5rem;
  margin: 2.5rem 0;
  border-radius: var(--cb-radius-lg);
  box-shadow: var(--cb-shadow-xl);
  text-align: center;
}

.cb-quote-marks-open,
.cb-quote-marks-close {
  font-size: 6rem;
  line-height: 1;
  color: rgba(255, 255, 255, 0.3);
  font-family: Georgia, serif;
  font-weight: bold;
  position: absolute;
  user-select: none;
}

.cb-quote-marks-open {
